contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address spender, uint256 amount) public payable {
        uint256 beforeAllowance = c.allowance(address(this), spender); if (__ESBMC_reverted()) return;
        if (beforeAllowance != 0 && amount != 0) {
            return;
        }
        bool success = c.approve(spender, amount); if (__ESBMC_reverted()) return;
        uint256 afterAllowance = c.allowance(address(this), spender); if (__ESBMC_reverted()) return;
        assert(success && afterAllowance == amount);
    }

    receive() external payable {}
}

